import { prisma } from "@/src/lib/prisma";
import CalendarClient from "components/calendar/CalendarClient";

export default async function CalendarPage() {
  // HATALI KISIM BURAYDI: prisma.task yerine prisma.calender kullanmalısın
  const calendarItems = await prisma.calender.findMany({
    orderBy: { 
      startDatetime: 'asc' 
    },
  });

  return (
    <div className="min-h-screen bg-[#070B24] p-8">
      {/* Veritabanından gelen gerçek takvim verilerini gönderiyoruz */}
      <CalendarClient initialTasks={calendarItems} />
    </div>
  );
}